// Score each channel's recent long-form videos against that channel's median
// views, keep only true outliers, and drop any video already sent in a
// previous run (tracked in workflow static data).
const config = $('Set your channels & limits').first().json;
const multiplier = Number(config.outlier_multiplier) || 3;
const minViews = Number(config.min_views) || 0;
const lookback = Number(config.lookback_videos) || 15;

const staticData = $getWorkflowStaticData('global');
staticData.sentOutliers ??= {};
const sent = staticData.sentOutliers;

const byChannel = {};
for (const { json: v } of $input.all()) {
  if (!v.channelName || !v.videoUrl) continue;
  (byChannel[v.channelName] ??= []).push(v);
}

const outliers = [];
for (const [channel, allVideos] of Object.entries(byChannel)) {
  const videos = allVideos.slice(0, lookback);
  const views = videos.map(v => v.viewCount || 0).sort((a, b) => a - b);
  if (!views.length) continue;
  const mid = Math.floor(views.length / 2);
  const median = views.length % 2 ? views[mid] : (views[mid - 1] + views[mid]) / 2;
  if (!median) continue;
  for (const v of videos) {
    const ratio = (v.viewCount || 0) / median;
    if (ratio < multiplier || (v.viewCount || 0) < minViews) continue;
    if (sent[v.videoUrl]) continue; // already sent in an earlier run
    sent[v.videoUrl] = new Date().toISOString();
    outliers.push({ json: {
      channel,
      title: v.videoTitle,
      url: v.videoUrl,
      views: v.viewCount,
      channel_median: Math.round(median),
      ratio: +ratio.toFixed(1),
      other_titles: videos.filter(o => o !== v).map(o => o.videoTitle).slice(0, 8),
    }});
  }
}
return outliers.sort((a, b) => b.json.ratio - a.json.ratio);

